class Solution {
    public int minimumEffort(int[][] tasks){
        Arrays.sort(tasks,(a,b)->Integer.compare(b[1]-b[0],a[1]-a[0]));
        int required=0,spent=0;
        for(int[] task:tasks){
            required=Math.max(required,spent+task[1]);
            spent+=task[0];
        }
        return required;
    }
}

code.kotlin:
class Solution {
    fun minimumEffort(tasks:Array<IntArray>):Int{
        tasks.sortWith(compareByDescending{
            it[1]-it[0]
        });
        var required=0;
        var spent=0;
        for(task in tasks){
            required=maxOf(required,spent+task[1]);
            spent+=task[0]
        };
        return required
    }
}

code.cpp:
class Solution {
    public: int minimumEffort(vector<vector<int>>& tasks){
        sort(tasks.begin(),tasks.end(),[](auto& a,auto& b){
            return a[1]-a[0]>b[1]-b[0];
        });
        int required=0,spent=0;
        for(auto& task:tasks){
            required=max(required,spent+task[1]);
            spent+=task[0];
        }
        return required;
    }
};
